files.content:
:root {
  --bg: #1a1c2c;
  --card-bg: #2a2d3e;
  --primary: #ffcd75;
  --secondary: #38b764;
  --text: #f4f4f4;
  --text-muted: #a0a0b0;
  --border: #4a4d5e;
  --focus: #ffcd75;
  --pressed: #e0b050;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  border-radius: 8px;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 24px;
  text-align: center;
  margin-bottom: 24px;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 2px;
}

.field {
  margin-bottom: 20px;
}

label, legend {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
  color: var(--text-muted);
  font-size: 16px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 4px;
  color: var(--text);
  font-size: 18px;
  font-family: inherit;
  transition: border-color 0.2s;
}

input[type="number"]:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 2px var(--focus);
}

.tip-buttons {
  display: flex;
  gap: 8px;
}

.tip-btn {
  flex: 1;
  padding: 12px 8px;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 4px;
  color: var(--text);
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
}

.tip-btn:hover {
  background: var(--border);
  border-color: var(--primary);
}

.tip-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  background: var(--pressed);
  transform: scale(0.97);
}

.tip-btn.active {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--bg);
}

.results {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 2px solid var(--border);
}

.result-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  font-size: 18px;
}

.result-item:last-child {
  margin-bottom: 0;
}

.result-label {
  color: var(--text-muted);
}

.result-value {
  font-weight: 700;
  color: var(--secondary);
  font-size: 20px;
}

@media (max-width: 360px) {
  .card {
    padding: 16px;
  }
  .tip-btn {
    padding: 10px 4px;
    font-size: 14px;
  }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipPerPersonEl = document.getElementById('tip-per-person');
  var totalPerPersonEl = document.getElementById('total-per-person');
  var tipButtons = document.querySelectorAll('.tip-btn');
  var selectedTip = 15; // default

  function updateActiveButton() {
    tipButtons.forEach(function (btn) {
      var tip = parseFloat(btn.getAttribute('data-tip'));
      if (tip === selectedTip) {
        btn.classList.add('active');
        btn.setAttribute('aria-pressed', 'true');
      } else {
        btn.classList.remove('active');
        btn.setAttribute('aria-pressed', 'false');
      }
    });
  }

  function calculate() {
    var bill = parseFloat(billInput.value) || 0;
    var people = parseInt(peopleInput.value, 10) || 1;
    if (bill < 0) bill = 0;
    if (people < 1) people = 1;

    var tipAmount = bill * (selectedTip / 100);
    var total = bill + tipAmount;
    var tipPerPerson = tipAmount / people;
    var totalPerPerson = total / people;

    tipPerPersonEl.textContent = '$' + tipPerPerson.toFixed(2);
    totalPerPersonEl.textContent = '$' + totalPerPerson.toFixed(2);
  }

  function onTipButtonClick(e) {
    var btn = e.currentTarget;
    selectedTip = parseFloat(btn.getAttribute('data-tip'));
    updateActiveButton();
    calculate();
  }

  function onInputChange() {
    calculate();
  }

  // Initialize
  updateActiveButton();
  calculate();

  // Event listeners
  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', onTipButtonClick);
  });

  billInput.addEventListener('input', onInputChange);
  peopleInput.addEventListener('input', onInputChange);
})();
